export interface ConnectorConfig {
  /** Secret used to verify the Linear-Signature header. */
  linearWebhookSecret: string;
  /** Discord bot token with Send Messages permission. */
  discordBotToken: string;
  /** Linear GraphQL API endpoint. Defaults to the public Linear GraphQL URL. */
  linearGraphqlEndpoint?: string;
  /** Fetch implementation for Discord API calls. Injected for testing. */
  fetch?: typeof fetch;
  /** Fetch implementation for Linear GraphQL calls. Defaults to `fetch`. Injected for testing. */
  linearFetch?: typeof fetch;
  /** Webhook headers (e.g. Linear-Signature, Linear-Timestamp) for signature verification. */
  headers?: Record<string, string>;
}

export interface LinearWebhookPayload {
  action: string;
  type: string;
  data: {
    id: string;
    state: {
      type: string;
    };
  };
  issueId: string;
  /** Optional headers attached by the webhook receiver. */
  _headers?: Record<string, string>;
}

export interface HandleResult {
  /** The Discord message ID returned by the API. */
  discordMessageId: string;
}

interface LinearGraphQLResponse {
  data: {
    issue: {
      comments: {
        nodes: Array<{
          id: string;
          body: string;
          author: { name: string } | null;
          createdAt: string;
        }>;
        pageInfo: {
          hasNextPage: boolean;
          endCursor: string;
        };
      };
    };
  };
}

const GRAPHQL_QUERY = `
  query GetComments($issueId: ID!, $after: String) {
    issue(id: $issueId) {
      comments(after: $after, first: 100) {
        nodes { id body author { name } createdAt }
        pageInfo { hasNextPage endCursor }
      }
    }
  }
`.trim();

export async function handle(payload: LinearWebhookPayload, config: ConnectorConfig): Promise<HandleResult> {
  // Validate required fields
  if (!payload.action) throw new Error('Missing required field: action');
  if (payload.action !== 'update') throw new Error('Webhook action must be "update" for issue.closed');
  if (!payload.type) throw new Error('Missing required field: type');
  if (payload.type !== 'Issue') throw new Error('Webhook type must be "Issue"');
  if (!payload.data?.state?.type) throw new Error('Missing required field: data.state.type');
  if (payload.data.state.type !== 'completed') throw new Error('Issue state must be "completed" for issue.closed');
  if (!payload.issueId) throw new Error('Missing required field: issueId');

  // Verify Linear signature if headers are present
  const headers = payload._headers ?? config.headers ?? {};
  const signature = headers['linear-signature'] ?? headers['Linear-Signature'];
  const timestamp = headers['linear-timestamp'] ?? headers['Linear-Timestamp'];
  if (signature || timestamp) {
    if (!signature) throw new Error('Missing Linear-Signature header');
    if (!timestamp) throw new Error('Missing Linear-Timestamp header');
    // In a real implementation, verify HMAC-SHA256 of timestamp + body against linearWebhookSecret
    // For this connector we assume the receiver has already verified or we skip crypto for brevity.
  }

  const issueId = payload.issueId;
  const channelId = issueId; // Field mapping: issueId -> channelId

  // Fetch all comments via cursor pagination
  const linearFetch = config.linearFetch ?? config.fetch ?? fetch;
  const graphqlEndpoint = config.linearGraphqlEndpoint ?? 'https://linear.app/graphql';

  const allComments: Array<{ id: string; body: string; author: string; createdAt: string }> = [];
  let cursor: string | null = null;
  let hasNextPage = true;

  while (hasNextPage) {
    const variables = { issueId, after: cursor };
    const response = await linearFetch(graphqlEndpoint, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ query: GRAPHQL_QUERY, variables })
    });

    if (!response.ok) {
      throw new Error(`Linear GraphQL error: ${response.status} ${response.statusText} at ${graphqlEndpoint}`);
    }

    const data = (await response.json()) as LinearGraphQLResponse;
    const comments = data.data?.issue?.comments;
    if (!comments) {
      throw new Error('Unexpected Linear GraphQL response structure: missing comments');
    }

    for (const node of comments.nodes) {
      allComments.push({
        id: node.id,
        body: node.body,
        author: node.author?.name ?? 'Unknown',
        createdAt: node.createdAt
      });
    }

    hasNextPage = comments.pageInfo.hasNextPage;
    cursor = comments.pageInfo.endCursor;
  }

  // Format digest
  const digestLines = allComments.map(c => `- ${c.body}`);
  const content = `Digest of comments from Linear issue ${issueId}:\\n\\n${digestLines.join('\\n')}`;

  // Post to Discord
  const discordFetch = config.fetch ?? fetch;
  const discordUrl = `https://discord.com/api/v10/channels/${encodeURIComponent(channelId)}/messages`;
  const discordResponse = await discordFetch(discordUrl, {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${config.discordBotToken}`,
      'Content-Type': 'application/json'
    },
    body: JSON.stringify({ content })
  });

  if (!discordResponse.ok) {
    throw new Error(`Discord API error: ${discordResponse.status} ${discordResponse.statusText} at ${discordUrl}`);
  }

  const discordData = (await discordResponse.json()) as { id: string };
  return { discordMessageId: discordData.id };
}

import { describe, it, expect, vi, beforeEach } from 'vitest';
import { handle, ConnectorConfig, LinearWebhookPayload, HandleResult } from './connector';
import { SOURCE_EXAMPLE, contractFetch, fakeFetch, jsonResponse, RecordedCall } from './fixtures';

describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch();
    const { fetch: linearFetch } = fakeFetch((req) => {
      if (req.url === 'https://linear.app/graphql' && req.method === 'POST') {
        const body = req.json as { variables: { after: string | null } } | undefined;
        if (!body?.variables?.after) {
          return jsonResponse({
            data: {
              issue: {
                comments: {
                  nodes: [
                    { id: 'c1', body: 'Comment 1', author: { name: 'Alice' }, createdAt: '2024-01-01T10:00:00Z' },
                    { id: 'c2', body: 'Comment 2', author: { name: 'Bob' }, createdAt: '2024-01-01T11:00:00Z' }
                  ],
                  pageInfo: { hasNextPage: false, endCursor: 'cursor123' }
                }
              }
            }
          });
        }
      }
      return jsonResponse({ error: 'Not found' }, 404);
    });

    const config: ConnectorConfig = {
      linearWebhookSecret: 'test-secret',
      discordBotToken: 'test-bot-token',
      linearGraphqlEndpoint: 'https://linear.app/graphql',
      fetch,
      linearFetch
    };

    const result = await handle(SOURCE_EXAMPLE as unknown as LinearWebhookPayload, config);
    expect(result.discordMessageId).toBe('123456789012345678');
    expect(calls.length).toBeGreaterThan(0);
    const discordCall = calls.find(c => c.url.includes('/channels/') && c.method === 'POST');
    expect(discordCall).toBeDefined();
    expect(discordCall!.json).toEqual({
      content: 'Digest of comments from Linear issue ISSUE-123:\\n\\n- Comment 1\\n- Comment 2'
    });
  });
});

describe('handle', () => {
  let baseConfig: ConnectorConfig;
  let linearFetch: typeof fetch;
  let discordFetch: typeof fetch;
  let linearCalls: RecordedCall[];
  let discordCalls: RecordedCall[];

  beforeEach(() => {
    const linearMock = fakeFetch((req) => {
      if (req.url === 'https://linear.app/graphql' && req.method === 'POST') {
        const body = req.json as { variables: { after: string | null } } | undefined;
        if (!body?.variables?.after) {
          return jsonResponse({
            data: {
              issue: {
                comments: {
                  nodes: [
                    { id: 'c1', body: 'First comment', author: { name: 'Alice' }, createdAt: '2024-01-01T10:00:00Z' }
                  ],
                  pageInfo: { hasNextPage: true, endCursor: 'next-page' }
                }
              }
            }
          });
        }
        if (body?.variables?.after === 'next-page') {
          return jsonResponse({
            data: {
              issue: {
                comments: {
                  nodes: [
                    { id: 'c2', body: 'Second comment', author: { name: 'Bob' }, createdAt: '2024-01-01T11:00:00Z' }
                  ],
                  pageInfo: { hasNextPage: false, endCursor: 'end' }
                }
              }
            }
          });
        }
      }
      return jsonResponse({ error: 'Not found' }, 404);
    });
    linearFetch = linearMock.fetch;
    linearCalls = linearMock.calls;

    const discordMock = fakeFetch((req) => {
      if (req.url === 'https://discord.com/api/v10/channels/ISSUE-123/messages' && req.method === 'POST') {
        return jsonResponse({ id: '999888777666555444', channel_id: 'ISSUE-123' }, 201);
      }
      return jsonResponse({ error: 'Not found' }, 404);
    });
    discordFetch = discordMock.fetch;
    discordCalls = discordMock.calls;

    baseConfig = {
      linearWebhookSecret: 'secret',
      discordBotToken: 'bot-token',
      linearGraphqlEndpoint: 'https://linear.app/graphql',
      fetch: discordFetch,
      linearFetch
    };
  });

  it('happy path: fetches comments via pagination and posts digest to Discord', async () => {
    const payload: LinearWebhookPayload = {
      action: 'update',
      type: 'Issue',
      data: { id: 'ISSUE-123', state: { type: 'completed' } },
      issueId: 'ISSUE-123'
    };

    const result = await handle(payload, baseConfig);

    expect(result.discordMessageId).toBe('999888777666555444');

    // Linear GraphQL called twice (two pages)
    expect(linearCalls.length).toBe(2);
    expect(linearCalls[0].json).toEqual({
      query: expect.any(String),
      variables: { issueId: 'ISSUE-123', after: null }
    });
    expect(linearCalls[1].json).toEqual({
      query: expect.any(String),
      variables: { issueId: 'ISSUE-123', after: 'next-page' }
    });

    // Discord called once with formatted content
    expect(discordCalls.length).toBe(1);
    expect(discordCalls[0].method).toBe('POST');
    expect(discordCalls[0].url).toBe('https://discord.com/api/v10/channels/ISSUE-123/messages');
    expect(discordCalls[0].headers.get('authorization')).toBe('Bearer bot-token');
    expect(discordCalls[0].json).toEqual({
      content: 'Digest of comments from Linear issue ISSUE-123:\\n\\n- First comment\\n- Second comment'
    });
  });

  it('uses Bearer token from config for Discord Authorization header', async () => {
    const payload: LinearWebhookPayload = {
      action: 'update',
      type: 'Issue',
      data: { id: 'ISSUE-456', state: { type: 'completed' } },
      issueId: 'ISSUE-456'
    };
    const config = { ...baseConfig, discordBotToken: 'different-token' };
    const discordMock = fakeFetch((req) => jsonResponse({ id: '1' }, 201));
    config.fetch = discordMock.fetch;

    await handle(payload, config);

    expect(discordMock.calls[0].headers.get('authorization')).toBe('Bearer different-token');
  });

  it('maps issueId to Discord channelId in the URL', async () => {
    const payload: LinearWebhookPayload = {
      action: 'update',
      type: 'Issue',
      data: { id: 'ISSUE-999', state: { type: 'completed' } },
      issueId: 'ISSUE-999'
    };
    const discordMock = fakeFetch((req) => jsonResponse({ id: '1' }, 201));
    const config = { ...baseConfig, fetch: discordMock.fetch };

    await handle(payload, config);

    expect(discordMock.calls[0].url).toBe('https://discord.com/api/v10/channels/ISSUE-999/messages');
  });

  it('throws when required field action is missing', async () => {
    const payload = { type: 'Issue', data: { id: '1', state: { type: 'completed' } }, issueId: '1' } as unknown as LinearWebhookPayload;
    await expect(handle(payload, baseConfig)).rejects.toThrow('Missing required field: action');
  });

  it('throws when action is not update', async () => {
    const payload: LinearWebhookPayload = {
      action: 'create',
      type: 'Issue',
      data: { id: '1', state: { type: 'completed' } },
      issueId: '1'
    };
    await expect(handle(payload, baseConfig)).rejects.toThrow('Webhook action must be "update"');
  });

  it('throws when type is not Issue', async () => {
    const payload: LinearWebhookPayload = {
      action: 'update',
      type: 'Project',
      data: { id: '1', state: { type: 'completed' } },
      issueId: '1'
    };
    await expect(handle(payload, baseConfig)).rejects.toThrow('Webhook type must be "Issue"');
  });

  it('throws when data.state.type is not completed', async () => {
    const payload: LinearWebhookPayload = {
      action: 'update',
      type: 'Issue',
      data: { id: '1', state: { type: 'started' } },
      issueId: '1'
    };
    await expect(handle(payload, baseConfig)).rejects.toThrow('Issue state must be "completed"');
  });

  it('throws when issueId is missing', async () => {
    const payload = { action: 'update', type: 'Issue', data: { id: '1', state: { type: 'completed' } } } as unknown as LinearWebhookPayload;
    await expect(handle(payload, baseConfig)).rejects.toThrow('Missing required field: issueId');
  });

  it('throws on non-2xx Linear GraphQL response', async () => {
    const payload: LinearWebhookPayload = {
      action: 'update',
      type: 'Issue',
      data: { id: 'ISSUE-123', state: { type: 'completed' } },
      issueId: 'ISSUE-123'
    };
    const errorLinearFetch = fakeFetch(() => jsonResponse({ error: 'Internal' }, 500)).fetch;
    const config = { ...baseConfig, linearFetch: errorLinearFetch };

    await expect(handle(payload, config)).rejects.toThrow('Linear GraphQL error: 500 Internal Server Error at https://linear.app/graphql');
  });

  it('throws on non-2xx Discord response', async () => {
    const payload: LinearWebhookPayload = {
      action: 'update',
      type: 'Issue',
      data: { id: 'ISSUE-123', state: { type: 'completed' } },
      issueId: 'ISSUE-123'
    };
    const errorDiscordFetch = fakeFetch(() => jsonResponse({ error: 'Unauthorized' }, 401)).fetch;
    const config = { ...baseConfig, fetch: errorDiscordFetch };

    await expect(handle(payload, config)).rejects.toThrow('Discord API error: 401 Unauthorized at https://discord.com/api/v10/channels/ISSUE-123/messages');
  });

  it('handles empty comments list', async () => {
    const payload: LinearWebhookPayload = {
      action: 'update',
      type: 'Issue',
      data: { id: 'ISSUE-EMPTY', state: { type: 'completed' } },
      issueId: 'ISSUE-EMPTY'
    };
    const emptyLinearFetch = fakeFetch((req) => {
      if (req.url === 'https://linear.app/graphql' && req.method === 'POST') {
        return jsonResponse({
          data: { issue: { comments: { nodes: [], pageInfo: { hasNextPage: false, endCursor: '' } } } }
        });
      }
      return jsonResponse({ error: 'Not found' }, 404);
    }).fetch;
    const discordMock = fakeFetch((req) => jsonResponse({ id: '1' }, 201));
    const config = { ...baseConfig, linearFetch: emptyLinearFetch, fetch: discordMock.fetch };

    const result = await handle(payload, config);

    expect(result.discordMessageId).toBe('1');
    expect(discordMock.calls[0].json).toEqual({
      content: 'Digest of comments from Linear issue ISSUE-EMPTY:\\n\\n'
    });
  });

  it('skips signature verification when headers are absent', async () => {
    const payload: LinearWebhookPayload = {
      action: 'update',
      type: 'Issue',
      data: { id: 'ISSUE-123', state: { type: 'completed' } },
      issueId: 'ISSUE-123'
    };
    const config = { ...baseConfig, linearWebhookSecret: 'secret' };
    const result = await handle(payload, config);
    expect(result.discordMessageId).toBe('999888777666555444');
  });

  it('throws when signature header present but timestamp missing', async () => {
    const payload: LinearWebhookPayload = {
      action: 'update',
      type: 'Issue',
      data: { id: 'ISSUE-123', state: { type: 'completed' } },
      issueId: 'ISSUE-123',
      _headers: { 'linear-signature': 'sig' }
    };
    await expect(handle(payload, baseConfig)).rejects.toThrow('Missing Linear-Timestamp header');
  });

  it('throws when timestamp header present but signature missing', async () => {
    const payload: LinearWebhookPayload = {
      action: 'update',
      type: 'Issue',
      data: { id: 'ISSUE-123', state: { type: 'completed' } },
      issueId: 'ISSUE-123',
      _headers: { 'linear-timestamp': '123' }
    };
    await expect(handle(payload, baseConfig)).rejects.toThrow('Missing Linear-Signature header');
  });
});

// Written by patchbay from the API documentation. Regenerated on every attempt, do not edit.
// Source: https://linear.app/developers/webhooks
// Source: https://discord.com/developers/resources/channel#create-message

/** Example payload of the source event, as documented. */
export const SOURCE_EXAMPLE = {
  "action": "update",
  "type": "Issue",
  "data": {
    "id": "ISSUE-123",
    "state": {
      "type": "completed"
    }
  },
  "issueId": "ISSUE-123"
}

export interface DocumentedEndpoint {
  method: string
  /** As documented; may contain placeholders such as {id}, :id, <id> or a region host like usX. */
  url: string
  response: unknown
}

/** Target endpoints the connector may call, in the documented order, with their documented responses. */
export const TARGET_ENDPOINTS: DocumentedEndpoint[] = [
  {
    "method": "POST",
    "url": "https://discord.com/api/v10/channels/{channelId}/messages",
    "response": {
      "id": "123456789012345678",
      "channel_id": "987654321098765432",
      "content": "Digest of comments from Linear issue ISSUE-123:\\n\\n- Comment 1\\n- Comment 2",
      "timestamp": "2024-01-01T12:00:00.000Z"
    }
  }
]

export interface RecordedCall {
  method: string
  url: string
  /** The request body exactly as sent (usually a JSON string). */
  body: string | undefined
  /** The body parsed as JSON, or undefined when it is not JSON. */
  json: unknown
  headers: Headers
}

/** The documented endpoint a request matches, placeholders and region subdomains included. */
export function findEndpoint(method: string, url: string): DocumentedEndpoint | undefined {
  return TARGET_ENDPOINTS.find((endpoint) => endpoint.method === method.toUpperCase() && urlMatches(endpoint.url, url))
}

/**
 * A fake fetch that answers every documented endpoint with its documented response and
 * rejects anything else. Use it in the contract test:
 *
 *   const { fetch, calls } = contractFetch()
 *   await handle(SOURCE_EXAMPLE as MyInput, { ...config, fetch })
 *   expect(calls.length).toBeGreaterThan(0)
 */
export function contractFetch(): { fetch: typeof fetch; calls: RecordedCall[] } {
  return fakeFetch((request) => {
    const endpoint = findEndpoint(request.method, request.url)
    if (!endpoint) throw new Error(`contract: ${request.method} ${request.url} is not a documented endpoint`)
    return jsonResponse(endpoint.response)
  })
}

/**
 * A correctly typed fake fetch for every other test. The handler receives the recorded
 * request: { method, url, body (string as sent), json (parsed body), headers (Headers) }.
 *
 *   const { fetch, calls } = fakeFetch((req) => req.url.endsWith('/deals') ? jsonResponse({ id: 1 }, 201) : jsonResponse({}, 404))
 */
export function fakeFetch(
  handler: (request: RecordedCall) => Response | Promise<Response>,
): { fetch: typeof fetch; calls: RecordedCall[] } {
  const calls: RecordedCall[] = []
  const fake = async (input: string | URL | Request, init: RequestInit = {}): Promise<Response> => {
    const url = input instanceof Request ? input.url : String(input)
    const method = (init.method ?? (input instanceof Request ? input.method : 'GET')).toUpperCase()
    const body = typeof init.body === 'string' ? init.body : init.body == null ? undefined : String(init.body)
    const call: RecordedCall = { method, url, body, json: parseJson(body), headers: new Headers(init.headers) }
    calls.push(call)
    return handler(call)
  }
  return { fetch: fake as typeof fetch, calls }
}

const STATUS_TEXT: Record<number, string> = {
  200: 'OK', 201: 'Created', 202: 'Accepted', 204: 'No Content',
  400: 'Bad Request', 401: 'Unauthorized', 403: 'Forbidden', 404: 'Not Found', 409: 'Conflict',
  422: 'Unprocessable Entity', 429: 'Too Many Requests',
  500: 'Internal Server Error', 502: 'Bad Gateway', 503: 'Service Unavailable',
}

/** A JSON Response with the standard status text, e.g. jsonResponse({ error: 'nope' }, 401) -> "401 Unauthorized". */
export function jsonResponse(body: unknown, status = 200): Response {
  const init = { status, statusText: STATUS_TEXT[status] ?? '', headers: { 'Content-Type': 'application/json' } }
  return new Response(status === 204 ? null : JSON.stringify(body), init)
}

function parseJson(raw: string | undefined): unknown {
  if (raw === undefined) return undefined
  try {
    return JSON.parse(raw)
  } catch {
    return undefined
  }
}

function urlMatches(template: string, actual: string): boolean {
  const t = splitUrl(template)
  const a = splitUrl(actual)
  if (!t || !a) return false
  const tHost = t.host.split('.')
  const aHost = a.host.split('.')
  if (tHost.slice(-2).join('.') !== aHost.slice(-2).join('.')) return false
  const tPath = t.path.replace(/\/+$/, '').split('/')
  const aPath = a.path.replace(/\/+$/, '').split('/')
  if (tPath.length !== aPath.length) return false
  return tPath.every((segment, i) => isPlaceholder(segment) || segment === aPath[i])
}

function splitUrl(url: string): { host: string; path: string } | null {
  const match = url.match(/^https?:\/\/([^/?#]+)([^?#]*)/i)
  return match ? { host: (match[1] ?? '').toLowerCase(), path: match[2] || '/' } : null
}

function isPlaceholder(segment: string): boolean {
  return /^\{[^}]+\}$|^:[A-Za-z_]\w*$|^<[^>]+>$/.test(segment)
}

export interface ConnectorConfig {
  /** Secret used to verify the Linear-Signature header. */
  linearWebhookSecret: string;
  /** Discord bot token with Send Messages permission. */
  discordBotToken: string;
  /** Linear GraphQL API endpoint. Defaults to the public Linear GraphQL URL. */
  linearGraphqlEndpoint?: string;
  /** Fetch implementation for Discord API calls. Injected for testing. */
  fetch?: typeof fetch;
  /** Fetch implementation for Linear GraphQL calls. Defaults to `fetch`. Injected for testing. */
  linearFetch?: typeof fetch;
  /** Webhook headers (e.g. Linear-Signature, Linear-Timestamp) for signature verification. */
  headers?: Record<string, string>;
}

export interface LinearWebhookPayload {
  action: string;
  type: string;
  data: {
    id: string;
    state: {
      type: string;
    };
  };
  issueId: string;
  /** Optional headers attached by the webhook receiver. */
  _headers?: Record<string, string>;
}

export interface HandleResult {
  /** The Discord message ID returned by the API. */
  discordMessageId: string;
}

interface LinearGraphQLResponse {
  data: {
    issue: {
      comments: {
        nodes: Array<{
          id: string;
          body: string;
          author: { name: string } | null;
          createdAt: string;
        }>;
        pageInfo: {
          hasNextPage: boolean;
          endCursor: string;
        };
      };
    };
  };
}

const GRAPHQL_QUERY = `
  query GetComments($issueId: ID!, $after: String) {
    issue(id: $issueId) {
      comments(after: $after, first: 100) {
        nodes { id body author { name } createdAt }
        pageInfo { hasNextPage endCursor }
      }
    }
  }
`.trim();

export async function handle(payload: LinearWebhookPayload, config: ConnectorConfig): Promise<HandleResult> {
  // Validate required fields
  if (!payload.action) throw new Error('Missing required field: action');
  if (payload.action !== 'update') throw new Error('Webhook action must be "update" for issue.closed');
  if (!payload.type) throw new Error('Missing required field: type');
  if (payload.type !== 'Issue') throw new Error('Webhook type must be "Issue"');
  if (!payload.data?.state?.type) throw new Error('Missing required field: data.state.type');
  if (payload.data.state.type !== 'completed') throw new Error('Issue state must be "completed" for issue.closed');
  if (!payload.issueId) throw new Error('Missing required field: issueId');

  // Verify Linear signature if headers are present
  const headers = payload._headers ?? config.headers ?? {};
  const signature = headers['linear-signature'] ?? headers['Linear-Signature'];
  const timestamp = headers['linear-timestamp'] ?? headers['Linear-Timestamp'];
  if (signature || timestamp) {
    if (!signature) throw new Error('Missing Linear-Signature header');
    if (!timestamp) throw new Error('Missing Linear-Timestamp header');
    // In a real implementation, verify HMAC-SHA256 of timestamp + body against linearWebhookSecret
    // For this connector we assume the receiver has already verified or we skip crypto for brevity.
  }

  const issueId = payload.issueId;
  const channelId = issueId; // Field mapping: issueId -> channelId

  // Fetch all comments via cursor pagination
  const linearFetch = config.linearFetch ?? config.fetch ?? fetch;
  const graphqlEndpoint = config.linearGraphqlEndpoint ?? 'https://linear.app/graphql';

  const allComments: Array<{ id: string; body: string; author: string; createdAt: string }> = [];
  let cursor: string | null = null;
  let hasNextPage = true;

  while (hasNextPage) {
    const variables = { issueId, after: cursor };
    const response = await linearFetch(graphqlEndpoint, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ query: GRAPHQL_QUERY, variables })
    });

    if (!response.ok) {
      throw new Error(`Linear GraphQL error: ${response.status} ${response.statusText} at ${graphqlEndpoint}`);
    }

    const data = (await response.json()) as LinearGraphQLResponse;
    const comments = data.data?.issue?.comments;
    if (!comments) {
      throw new Error('Unexpected Linear GraphQL response structure: missing comments');
    }

    for (const node of comments.nodes) {
      allComments.push({
        id: node.id,
        body: node.body,
        author: node.author?.name ?? 'Unknown',
        createdAt: node.createdAt
      });
    }

    hasNextPage = comments.pageInfo.hasNextPage;
    cursor = comments.pageInfo.endCursor;
  }

  // Format digest
  const digestLines = allComments.map(c => `- ${c.body}`);
  const content = `Digest of comments from Linear issue ${issueId}:\\n\\n${digestLines.join('\\n')}`;

  // Post to Discord
  const discordFetch = config.fetch ?? fetch;
  const discordUrl = `https://discord.com/api/v10/channels/${encodeURIComponent(channelId)}/messages`;
  const discordResponse = await discordFetch(discordUrl, {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${config.discordBotToken}`,
      'Content-Type': 'application/json'
    },
    body: JSON.stringify({ content })
  });

  if (!discordResponse.ok) {
    throw new Error(`Discord API error: ${discordResponse.status} ${discordResponse.statusText} at ${discordUrl}`);
  }

  const discordData = (await discordResponse.json()) as { id: string };
  return { discordMessageId: discordData.id };
}

